#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets these two at the top of the stages section.
TOTAL_STAGES=0
TOTAL_MINUTES=0

_STAGE_INDEX=0
_MINUTES_ELAPSED=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does and how long it takes.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages · about %s minutes%s\n\n' \
    "$DIM" "$TOTAL_STAGES" "$TOTAL_MINUTES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" <minutes> — clear the screen, then announce a stage and show
# progress + time remaining. Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  local remaining=$((TOTAL_MINUTES - _MINUTES_ELAPSED))
  (( remaining < 0 )) && remaining=0
  _MINUTES_ELAPSED=$((_MINUTES_ELAPSED + ${2:-0}))
  printf '\n%s%s▸ Stage %s/%s · %s%s  %s(~%s min left)%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET" "$DIM" "$remaining" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — GitHub App setup for the self-hosted repository worker.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=7
TOTAL_MINUTES=15

REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$REPO_ROOT"
ENV_FILE="${ENV_FILE:-$REPO_ROOT/.idp/github-app.env}"
CONFIG_FILE="${INSTALLATION_CONFIG:-$REPO_ROOT/.idp/config.json}"
KEY_DIRECTORY="$REPO_ROOT/.idp/secrets"
KEY_FILE="$KEY_DIRECTORY/github-app.pem"
REUSE_EXISTING=false
PRIVATE_KEY_SOURCE_PATH=""

banner "Platform IDP · GitHub App setup"

stage "Check local installation" 1
say "We'll read the GitHub organization from the guided installer config."
if [[ ! -f "$CONFIG_FILE" ]]; then
  warn "missing installation config: $CONFIG_FILE"
  say "Run: go run ./cmd/idp-bootstrap configure --config .idp/config.json"
  exit 1
fi
if ! command -v jq >/dev/null 2>&1; then
  warn "jq is required to read the installation config safely."
  exit 1
fi
GITHUB_ORGANIZATION=$(jq -er '.github.organization | select(type == "string" and length > 0)' "$CONFIG_FILE") || {
  warn "github.organization is missing from $CONFIG_FILE"
  exit 1
}
say "Organization: $GITHUB_ORGANIZATION"
say "The wizard stores secrets only under the Git-ignored .idp directory."
if [[ -f "$ENV_FILE" && -f "$KEY_FILE" && ! -L "$KEY_FILE" ]]; then
  EXISTING_APP_ID=$(sed -n 's/^GITHUB_APP_ID=\([1-9][0-9]*\)$/\1/p' "$ENV_FILE" | tail -n 1)
  EXISTING_INSTALLATION_ID=$(sed -n 's/^GITHUB_APP_INSTALLATION_ID=\([1-9][0-9]*\)$/\1/p' "$ENV_FILE" | tail -n 1)
  if [[ -n "$EXISTING_APP_ID" && -n "$EXISTING_INSTALLATION_ID" ]] && confirm "Reuse the existing GitHub App configuration and run preflight?"; then
    GITHUB_APP_ID="$EXISTING_APP_ID"
    GITHUB_APP_INSTALLATION_ID="$EXISTING_INSTALLATION_ID"
    REUSE_EXISTING=true
    say "Reusing the existing App and secured private key. Registration steps will be skipped."
  fi
fi
pause "Continue to GitHub App registration?"

stage "Register the GitHub App" 5
if [[ "$REUSE_EXISTING" == true ]]; then
  say "Using App ID $GITHUB_APP_ID from the existing local configuration."
else
  say "Create a private app owned by $GITHUB_ORGANIZATION."
  warn "All-repository access grants this App write access to every repository in the organization. Prefer a dedicated organization for this control plane."
  open_url "https://github.com/organizations/$GITHUB_ORGANIZATION/settings/apps/new"
step "Choose a globally unique name, for example: $GITHUB_ORGANIZATION-platform-idp."
step "Set Homepage URL to https://github.com/OcheOps/platform-IDP."
step "Leave callback and setup URLs empty. Do not request user authorization."
step "Disable the webhook. No event subscriptions are needed for this worker."
step "Repository permissions: Administration — Read and write."
step "Repository permissions: Checks — Read-only."
step "Repository permissions: Contents — Read and write."
step "Repository permissions: Pull requests — Read-only."
step "Repository permissions: Commit statuses — Read-only."
step "Repository permissions: Workflows — Read and write."
step "Repository permissions: Metadata — Read-only (GitHub may select this automatically)."
step "Organization permissions: Members — Read-only."
step "Under installation scope, select 'Only on this account'."
step "Click 'Create GitHub App'."
pause "Press Enter when the App's General settings page is open."
step "Copy the numeric App ID shown on the General settings page."
ask GITHUB_APP_ID "Paste the App ID:"
if [[ ! "$GITHUB_APP_ID" =~ ^[1-9][0-9]*$ ]]; then
  warn "App ID must be a positive integer."
  exit 1
fi
fi

stage "Generate and secure the private key" 2
if [[ "$REUSE_EXISTING" == true ]]; then
  say "Keeping the existing owner-only key at $KEY_FILE."
else
  say "Stay on the App's General settings page."
step "Scroll to 'Private keys' and click 'Generate a private key'."
step "GitHub downloads a .pem file. Keep it private."
ask PRIVATE_KEY_SOURCE_PATH "Paste the absolute path to the downloaded .pem file:"
if [[ "$PRIVATE_KEY_SOURCE_PATH" != /* || "$PRIVATE_KEY_SOURCE_PATH" =~ [[:space:]] ]]; then
  warn "Use an absolute path without whitespace."
  exit 1
fi
if [[ ! -f "$PRIVATE_KEY_SOURCE_PATH" || -L "$PRIVATE_KEY_SOURCE_PATH" ]]; then
  warn "The private key must be a regular file, not a symlink."
  exit 1
fi
mkdir -p "$KEY_DIRECTORY"
chmod 700 "$KEY_DIRECTORY"
if [[ "$PRIVATE_KEY_SOURCE_PATH" != "$KEY_FILE" && -e "$KEY_FILE" ]] && ! confirm "Replace the existing secured GitHub App key?"; then
  warn "kept the existing key; setup stopped before changing runtime values"
  exit 1
fi
if [[ "$PRIVATE_KEY_SOURCE_PATH" == "$KEY_FILE" ]]; then
  chmod 600 "$KEY_FILE"
else
  install -m 600 -- "$PRIVATE_KEY_SOURCE_PATH" "$KEY_FILE"
fi
say "Secured the key at $KEY_FILE with owner-only permissions."
fi

stage "Install the App" 3
if [[ "$REUSE_EXISTING" == true ]]; then
  say "Using Installation ID $GITHUB_APP_INSTALLATION_ID from the existing local configuration."
else
  say "Install the App into $GITHUB_ORGANIZATION."
open_url "https://github.com/organizations/$GITHUB_ORGANIZATION/settings/apps"
step "Open the App, then select 'Install App' in its settings sidebar."
step "Choose $GITHUB_ORGANIZATION."
step "Select 'All repositories' so newly generated repositories are immediately accessible."
step "Click 'Install' and wait for the installation settings page."
step "The address bar ends with /settings/installations/<number>. Copy that number."
ask GITHUB_APP_INSTALLATION_ID "Paste the Installation ID:"
if [[ ! "$GITHUB_APP_INSTALLATION_ID" =~ ^[1-9][0-9]*$ ]]; then
  warn "Installation ID must be a positive integer."
  exit 1
fi
fi

stage "Write worker runtime settings" 1
say "Only non-secret IDs and local file paths go into the environment file."
mkdir -p "$(dirname "$ENV_FILE")"
touch "$ENV_FILE"
chmod 600 "$ENV_FILE"
write_env GITHUB_APP_ID "$GITHUB_APP_ID"
write_env GITHUB_APP_INSTALLATION_ID "$GITHUB_APP_INSTALLATION_ID"
write_env GITHUB_APP_PRIVATE_KEY_FILE "$KEY_FILE"
write_env INSTALLATION_CONFIG "$CONFIG_FILE"
write_env GENERATED_DIRECTORY "$REPO_ROOT/.platform-data"
chmod 600 "$ENV_FILE"

stage "Validate credentials and permissions" 2
say "This read-only preflight signs a JWT and requests a short-lived installation token."
if env \
  GITHUB_APP_ID="$GITHUB_APP_ID" \
  GITHUB_APP_INSTALLATION_ID="$GITHUB_APP_INSTALLATION_ID" \
  GITHUB_APP_PRIVATE_KEY_FILE="$KEY_FILE" \
  INSTALLATION_CONFIG="$CONFIG_FILE" \
  GENERATED_DIRECTORY="$REPO_ROOT/.platform-data" \
  go run ./cmd/repository-worker --preflight; then
  say "GitHub App organization, all-repository scope, authentication, and exact permissions are valid."
else
  warn "Preflight failed. Recheck the App ID, Installation ID, key, installation scope, and permissions."
  exit 1
fi

stage "Ready to run" 1
say "Start the development worker with:"
say "  ./scripts/run-repository-worker.sh"
note "The worker mints short-lived installation tokens. It never uses a personal access token."
note "Keep .idp/secrets/github-app.pem backed up in a secure secret manager, not Git."
if [[ -n "$PRIVATE_KEY_SOURCE_PATH" && "$PRIVATE_KEY_SOURCE_PATH" != "$KEY_FILE" ]]; then
  if confirm "Delete the original downloaded private key now that the secured copy is valid?"; then
    rm -- "$PRIVATE_KEY_SOURCE_PATH"
    say "Deleted the original downloaded key. The secured copy remains at $KEY_FILE."
  else
    warn "The original key remains at $PRIVATE_KEY_SOURCE_PATH. Securely archive or delete it."
  fi
fi

finish
